place.fagverk={schema:"history_go_place_fagverk_v2",level:"standard",status:"curated",intro:"Norske Grafikere gjør grafikkens institusjonelle historie lesbar gjennom undervisning, kunstnerorganisering, galleri, program og støtteordninger.",article:["Johan Nordhagens Radérklasse fra 1899 bidro til et fagmiljø som kunne organisere seg i 1919. Stiftelsesprotokollen viser at et medium ikke bare utvikles gjennom enkeltverk, men også gjennom undervisning, nettverk og felles krav om bedre trykke- og utstillingsforhold.","Galleriet fra 1972 var kunstnerstyrt og mottok statlig støtte. Kombinasjonen gjør stedet egnet for institusjonsanalyse: kunstnerisk autonomi eksisterer sammen med lokaler, finansiering, juryer, salg og formidling. Flyttingen til Tollbugata 24 i 2002 gir denne organisasjonen et varig offentlig sted.","Programverkene fra 2026 viser at grafikk ikke er én teknikk: litografi, karbontrykk og pigmenttrykk på bomull inngår i samme institusjonelle ramme. Norske Grafikeres Fond viser samtidig hvordan økonomiske virkemidler kan støtte feltet. En analyse må skille mellom verkets materiale, galleriets utvalg, foreningens interesser og fondets beslutninger."],subject_ids:["kunst"],emne_ids:["em_kunst_institusjoner_kanon","em_kunst_materialitet_teknikk_handverk","em_kunst_okonomi_og_finansiering"],chapter_ids:["felt_institusjon","produksjon_praksis","makt_legitimitet"],lenses:[{id:"norske-grafikere-institusjon",title:"Kunstnere bygger institusjon",prompt:"Hvordan endret kontoret og galleriet grafikernes mulighet til å vise og legitimere egne arbeider?",subject_id:"kunst",emne_id:"em_kunst_institusjoner_kanon",evidence:"Knytt 1971, 1972 og 2002 til organisering, galleri og varig adresse."},{id:"norske-grafikere-materialitet",title:"Grafikk er flere teknikker",prompt:"Hva viser programverkene om forholdet mellom medium, materiale og institusjon?",subject_id:"kunst",emne_id:"em_kunst_materialitet_teknikk_handverk",evidence:"Sammenlign litografi, karbontrykk på papir og pigmenttrykk på bomull."},{id:"norske-grafikere-okonomi",title:"Støtte former muligheter",prompt:"Hvordan inngår statlig støtte og fondsmidler i grafikkfeltets infrastruktur?",subject_id:"kunst",emne_id:"em_kunst_okonomi_og_finansiering",evidence:"Skill galleriets statlige støtte fra fondets stipend, prosjektmidler og grafikkpris."}],guiding_questions:["Hvordan ble undervisningsmiljø til kunstnerorganisasjon?","Hva betyr kunstnerstyrt når galleriet også mottar offentlig støtte?","Hvordan viser programmet bredden i grafiske medier?","Hvilke valg gjør et galleri når det setter et program?","Hvorfor må forening og fond skilles analytisk?"],concepts:["originalgrafikk","kunstnerorganisering","institusjonell legitimering","materialitet","kuratering","kunstnerøkonomi"],observable_traces:[{title:"Gallerirommet",observation:"Tollbugata 24 gir foreningen et offentlig visnings- og formidlingsrom.",interpretation_boundary:"Et besøk viser dagens rom og program, men ikke hele institusjonshistorien.",source_urls:[urls.official,urls.visit]},{title:"Programverk",observation:"Skiftende verk viser flere grafiske teknikker og materialer.",interpretation_boundary:"Programmet dokumenterer en datert visning, ikke en permanent samling.",source_urls:[urls.program]}],source_urls:[urls.official,urls.program,urls.fund,urls.original],verified_at:verifiedAt};
