const lexFile="data/leksikon/places/oslo/kunst/leksikon_norske_grafikere.json";write(lexFile,{place_id:placeId,title:"Norske Grafikere",type:"main",version:1,visual:{designCode:"article_place_essay_miniature"},popupDesc:"Fra Radérklassen og stiftelsesprotokollen til kunstnerstyrt galleri, fond og samtidsgrafikk.",wikiText:["Norske Grafikere ble stiftet 15. november 1919 av et miljø der flere initiativtakere hadde bakgrunn fra Johan Nordhagens Radérklasse. Foreningen samlet 30 medlemmer ved starten og arbeidet for bedre trykke- og utstillingsforhold.","Et eget kontor kom i 1971, og i 1972 åpnet foreningen et kunstnerstyrt galleri med statlig støtte. Etter flere adresser flyttet den til Tollbugata 24 i 2002.","Galleriet viser grafikk som et mangfold av teknikker og materialer. Norske Grafikeres Fond finansieres gjennom bibliotekvederlag og må forstås som en egen aktør i feltets økonomiske infrastruktur."],summary:{one_liner:"Grafikerforening fra 1919 med kunstnerstyrt galleri i Tollbugata 24.",themes:["grafikk","kunstnerorganisering","galleri","institusjon","økonomi"],tone:["nøktern","kunstfaglig"]},facts:[{id:"fact_ng_1919",label:"Stiftelsen",desc:"Foreningen ble stiftet 15. november 1919.",confidence:"high",sources:[{title:"Norske Grafikere",url:urls.official}]},{id:"fact_ng_1972",label:"Galleriet",desc:"Det kunstnerstyrte galleriet med statlig støtte åpnet i 1972.",confidence:"high",sources:[{title:"Norske Grafikere",url:urls.official}]},{id:"fact_ng_2002",label:"Adressen",desc:"Tollbugata 24 har vært adressen siden 2002.",confidence:"high",sources:[{title:"Norske Grafikere",url:urls.official}]}],chronology,sources:place.externalLinks,externalLinks:place.externalLinks,interpretation:place.interpretation});const lm=read("data/leksikon/manifest.json");addOnce(lm.files,lexFile);write("data/leksikon/manifest.json",lm);
