const storyFile="data/stories/stories_norske_grafikere.json";const story={id:"st_norske_grafikere_53_ar_til_galleri",quality_profile:"episode_v1",type:"turning_point",title:"53 år til et eget galleri",year:1972,place_id:placeId,summary:"Fra stiftelsesprotokollen i 1919 tok det 53 år før Norske Grafikere åpnet sitt eget kunstnerstyrte galleri.",story:"Lørdag 15. november 1919 samlet grafikere seg for å stifte Norske Grafikere. De ville bedre grafikkens kår, blant annet gjennom bedre tilgang til trykking og egne utstillingsmuligheter. Protokollen fra møtet viser at organiseringen startet lenge før foreningen hadde et fast galleri.\n\nTiårene gikk med juryarbeid, samarbeid og skiftende utstillinger. Først i 1971 fikk foreningen eget kontor, drevet fram mens Anne Breivik var styreleder. Det administrative rommet ble et konkret steg mot et offentlig visningssted.\n\nI 1972 åpnet Norske Grafikere sitt eget galleri i Hegdehaugsveien, beskrevet som det første kunstnerstyrte galleriet med statlig støtte. Femti tre år etter stiftelsen hadde kravet om bedre utstillingsmuligheter fått en varig institusjonell form. Dagens adresse i Tollbugata 24 kom senere, i 2002.",episode:{actors:["medlemmene i Norske Grafikere","Anne Breivik"],date:"1972",action:"Foreningen åpnet sitt kunstnerstyrte galleri med statlig støtte.",consequence:"Grafikerne fikk et varig institusjonelt rom for utstillinger, salg og formidling."},sources:[{title:"Norske Grafikere – om oss",url:urls.official},{title:"Norske Grafikeres galleri fyller 50 år",url:urls.gallery50}],tags:["grafikk","kunstnerorganisering","galleri","1919","1972"],related_people:[personId],related_places:[],next_scenes:[],score:{narrative:3,historical:2,source:4,play_value:3,originality:3,total:15},arc:{start:"Grafikere samles rundt en protokoll og to praktiske krav.",middle:"Organisasjonen arbeider i tiår uten eget galleri.",end:"I 1972 blir utstillingskravet til et kunstnerstyrt galleri."}};write(storyFile,[story]);const stm=read("data/stories/stories_manifest.json");stm.files=stm.files.filter(x=>x.entity_id!==placeId);stm.files.push({category:"kunst",entity_id:placeId,path:storyFile});write("data/stories/stories_manifest.json",stm);const sem=read("data/stories/stories_episode_v1_manifest.json");addOnce(sem.files,storyFile);write("data/stories/stories_episode_v1_manifest.json",sem);
